import { useState } from 'react';

type Workspace = { name: string; ready: boolean };

export function Studio({ name }: Workspace) {
  const [count, setCount] = useState(42);
  return <button onClick={() => setCount(count + 1)}>
    {name}: {count} — 0O 1lI => !==
  </button>;
}

